CREATE TYPE "ChangeLifecycle" AS ENUM ('DRAFT','SUBMITTED','IMPACT_ANALYZING','RISK_ASSESSING','PLAN_GENERATED','REVIEW_REQUIRED','APPROVAL_REQUIRED','APPROVED','REHEARSAL_REQUIRED','REHEARSING','REHEARSAL_CERTIFIED','READY_FOR_RELEASE','RELEASE_WINDOW_OPEN','DEPLOYING','POST_DEPLOYMENT_VALIDATING','VERIFIED','CERTIFIED','REJECTED','BLOCKED','ABORTED','ROLLED_BACK','ROLLBACK_FAILED','FAILED','EXPIRED','SUPERSEDED','CANCELLED');
CREATE TYPE "ChangeRisk" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL','PROHIBITED');
CREATE TYPE "ChangeApprovalDecision" AS ENUM ('APPROVED','REJECTED','EXPIRED');
CREATE TYPE "ChangeRehearsalStatus" AS ENUM ('REQUIRED','RUNNING','CERTIFIED','FAILED','BLOCKED','EXPIRED');
CREATE TYPE "ChangeReleaseStatus" AS ENUM ('PLANNED','WINDOW_OPEN','DEPLOYING','VALIDATING','VERIFIED','HALTED','ROLLED_BACK','FAILED','CLOSED');
CREATE TYPE "ChangeValidationResult" AS ENUM ('PASS','FAIL','UNKNOWN');
CREATE TYPE "ChangeCertificationStatus" AS ENUM ('CERTIFIED','STALE','REVOKED','FAILED');
CREATE TYPE "ChangeEvidenceType" AS ENUM ('IMPACT_ANALYSIS','POLICY_DECISION','APPROVAL','GRAPH_SNAPSHOT','REHEARSAL','SIMULATION','DEPLOYMENT','TEST','MONITORING','SLO','RECONCILIATION','SECURITY','PRIVACY','COST','ROLLBACK','CERTIFICATION');
CREATE TABLE "ChangeRequest" ("id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"title" VARCHAR(240) NOT NULL,"purpose" VARCHAR(2000) NOT NULL,"rationale" VARCHAR(2000) NOT NULL,"scope" JSONB NOT NULL,"targets" JSONB NOT NULL,"category" VARCHAR(64) NOT NULL,"urgency" VARCHAR(40) NOT NULL,"environment" VARCHAR(80) NOT NULL,"requestedWindow" VARCHAR(120),"requesterId" VARCHAR(120) NOT NULL,"ownerId" VARCHAR(120) NOT NULL,"businessImpact" JSONB NOT NULL,"customerImpact" JSONB NOT NULL,"technicalImpact" JSONB NOT NULL,"rollbackStrategy" VARCHAR(2000) NOT NULL,"validationStrategy" VARCHAR(2000) NOT NULL,"requiredApprovals" JSONB NOT NULL,"status" "ChangeLifecycle" NOT NULL DEFAULT 'DRAFT',"risk" "ChangeRisk" NOT NULL DEFAULT 'LOW',"revision" INTEGER NOT NULL DEFAULT 1,"version" INTEGER NOT NULL DEFAULT 1,"policyVersion" VARCHAR(80) NOT NULL,"correlationId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ChangeRequest_stableId_key" ON "ChangeRequest"("stableId");
CREATE INDEX "ChangeRequest_status_risk_updatedAt_idx" ON "ChangeRequest"("status","risk","updatedAt");
CREATE INDEX "ChangeRequest_environment_category_idx" ON "ChangeRequest"("environment","category");
CREATE TABLE "ChangeRiskAssessment" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"risk" "ChangeRisk" NOT NULL,"reasons" JSONB NOT NULL,"signals" JSONB NOT NULL,"methodologyVersion" VARCHAR(80) NOT NULL,"confidence" VARCHAR(32) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRiskAssessment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeRiskAssessment_changeRequestId_createdAt_idx" ON "ChangeRiskAssessment"("changeRequestId","createdAt");
CREATE TABLE "ChangeImpact" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"directAffected" JSONB NOT NULL,"indirectAffected" JSONB NOT NULL,"transitiveAffected" JSONB NOT NULL,"unknownAffected" JSONB NOT NULL,"customerImpact" JSONB NOT NULL,"operationalImpact" JSONB NOT NULL,"financialImpact" JSONB NOT NULL,"securityImpact" JSONB NOT NULL,"privacyImpact" JSONB NOT NULL,"reliabilityImpact" JSONB NOT NULL,"performanceImpact" JSONB NOT NULL,"capacityImpact" JSONB NOT NULL,"dataIntegrityImpact" JSONB NOT NULL,"providerImpact" JSONB NOT NULL,"architecturalImpact" JSONB NOT NULL,"blastRadius" "ChangeRisk" NOT NULL,"confidence" VARCHAR(32) NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeImpact_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeImpact_changeRequestId_createdAt_idx" ON "ChangeImpact"("changeRequestId","createdAt");
CREATE TABLE "ChangePlan" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"version" INTEGER NOT NULL,"status" VARCHAR(32) NOT NULL,"executionMode" VARCHAR(64) NOT NULL,"steps" JSONB NOT NULL,"planHash" VARCHAR(128) NOT NULL,"generatedBy" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangePlan_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangePlan_changeRequestId_createdAt_idx" ON "ChangePlan"("changeRequestId","createdAt");
CREATE TABLE "ChangeApproval" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"actorId" VARCHAR(120) NOT NULL,"approvalType" VARCHAR(64) NOT NULL,"decision" "ChangeApprovalDecision" NOT NULL,"revision" INTEGER NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"evidenceHash" VARCHAR(128) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeApproval_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeApproval_changeRequestId_createdAt_idx" ON "ChangeApproval"("changeRequestId","createdAt");
CREATE TABLE "ChangeRehearsal" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"status" "ChangeRehearsalStatus" NOT NULL,"environment" VARCHAR(80) NOT NULL,"simulationOnly" BOOLEAN NOT NULL DEFAULT true,"requestedBy" VARCHAR(120) NOT NULL,"certifiedBy" VARCHAR(120),"certifiedAt" TIMESTAMP(3),"result" VARCHAR(32),"evidence" JSONB,"correlationId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRehearsal_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeRehearsal_changeRequestId_createdAt_idx" ON "ChangeRehearsal"("changeRequestId","createdAt");
CREATE TABLE "ChangeRelease" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"status" "ChangeReleaseStatus" NOT NULL,"releaseReference" VARCHAR(160) NOT NULL,"windowReference" VARCHAR(160) NOT NULL,"authorizedBy" VARCHAR(120) NOT NULL,"lastActorId" VARCHAR(120),"deploymentReference" VARCHAR(160),"correlationId" VARCHAR(120) NOT NULL,"startedAt" TIMESTAMP(3),"validatedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRelease_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeRelease_changeRequestId_createdAt_idx" ON "ChangeRelease"("changeRequestId","createdAt");
CREATE TABLE "ChangeValidation" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"result" "ChangeValidationResult" NOT NULL,"checks" JSONB NOT NULL,"validatedBy" VARCHAR(120) NOT NULL,"correlationId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeValidation_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeValidation_changeRequestId_createdAt_idx" ON "ChangeValidation"("changeRequestId","createdAt");
CREATE TABLE "ChangeRollback" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"trigger" VARCHAR(80) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"action" VARCHAR(160) NOT NULL,"result" VARCHAR(32) NOT NULL,"actorId" VARCHAR(120) NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRollback_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeRollback_changeRequestId_createdAt_idx" ON "ChangeRollback"("changeRequestId","createdAt");
CREATE TABLE "ChangeEvidence" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"evidenceType" "ChangeEvidenceType" NOT NULL,"source" VARCHAR(160) NOT NULL,"reference" VARCHAR(255) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"immutable" BOOLEAN NOT NULL DEFAULT true,"capturedBy" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeEvidence_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeEvidence_changeRequestId_createdAt_idx" ON "ChangeEvidence"("changeRequestId","createdAt");
CREATE TABLE "ChangeCertification" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"status" "ChangeCertificationStatus" NOT NULL,"version" INTEGER NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"graphSnapshotId" UUID,"rehearsalReference" VARCHAR(160),"validationEvidence" JSONB NOT NULL,"deploymentEvidence" JSONB NOT NULL,"approvalEvidence" JSONB NOT NULL,"certifiedBy" VARCHAR(120) NOT NULL,"validUntil" TIMESTAMP(3) NOT NULL,"invalidationConditions" JSONB NOT NULL,"invalidationReason" VARCHAR(500),"certifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeCertification_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeCertification_changeRequestId_certifiedAt_idx" ON "ChangeCertification"("changeRequestId","certifiedAt");
CREATE TABLE "ChangeGraphSnapshot" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"graphVersion" VARCHAR(80) NOT NULL,"graphFreshness" VARCHAR(32) NOT NULL,"unresolvedNodes" JSONB NOT NULL,"unresolvedRelationships" JSONB NOT NULL,"confidence" VARCHAR(32) NOT NULL,"staleDependencies" JSONB NOT NULL,"unknownDependencies" JSONB NOT NULL,"snapshot" JSONB NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeGraphSnapshot_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeGraphSnapshot_changeRequestId_createdAt_idx" ON "ChangeGraphSnapshot"("changeRequestId","createdAt");
CREATE TABLE "ChangeDependencySnapshot" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"version" VARCHAR(80) NOT NULL,"dependencies" JSONB NOT NULL,"unknownDependencies" JSONB NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeDependencySnapshot_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeDependencySnapshot_changeRequestId_capturedAt_idx" ON "ChangeDependencySnapshot"("changeRequestId","capturedAt");
CREATE TABLE "ChangeDecision" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"decision" VARCHAR(80) NOT NULL,"actorId" VARCHAR(120) NOT NULL,"fromStatus" VARCHAR(64),"toStatus" VARCHAR(64),"revision" INTEGER NOT NULL,"correlationId" VARCHAR(120) NOT NULL,"evidenceHash" VARCHAR(128) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeDecision_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeDecision_changeRequestId_createdAt_idx" ON "ChangeDecision"("changeRequestId","createdAt");
CREATE TABLE "ChangePolicyDecision" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"decision" VARCHAR(64) NOT NULL,"matchedRules" JSONB NOT NULL,"failedRules" JSONB NOT NULL,"evidence" JSONB NOT NULL,"evaluatorVersion" VARCHAR(80) NOT NULL,"actorId" VARCHAR(120) NOT NULL,"correlationId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangePolicyDecision_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangePolicyDecision_changeRequestId_createdAt_idx" ON "ChangePolicyDecision"("changeRequestId","createdAt");
CREATE TABLE "ChangeObservation" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"metric" VARCHAR(120) NOT NULL,"status" VARCHAR(32) NOT NULL,"value" JSONB NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeObservation_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeObservation_changeRequestId_createdAt_idx" ON "ChangeObservation"("changeRequestId","createdAt");
CREATE TABLE "ChangeIncident" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"incidentReference" VARCHAR(160) NOT NULL,"causalityConfidence" VARCHAR(32) NOT NULL,"details" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeIncident_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeIncident_changeRequestId_createdAt_idx" ON "ChangeIncident"("changeRequestId","createdAt");
CREATE TABLE "ChangeLock" ("id" UUID NOT NULL,"changeRequestId" UUID NOT NULL,"scope" VARCHAR(160) NOT NULL,"ownerId" VARCHAR(120) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"heartbeatAt" TIMESTAMP(3),"status" VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeLock_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChangeLock_changeRequestId_createdAt_idx" ON "ChangeLock"("changeRequestId","createdAt");
